@startuml

enum UserState {
  New
  Active
  Temporary Blocked
  Banned
}

class Customer {
  + id : string
}

class WebUser extends Customer {
  + login_name : string
}

class Account {
  + id : string
}

class ShoppingCart {
  + id : string
}

class Order {
  + number : string
  + status : string
}

class LineItem {
  + quantity : int
  + price : double
}

class Payment {
  + id : string
}

class Product {
  + id : string
  + name : string
}

Customer "1" -- "1" Account
Account "1" *-- "1" ShoppingCart
Account "1" *-- "*" Order
Account "1" -- "*" Payment
Customer "0..1" -- "1" ShoppingCart
Order "1" *-- "*" LineItem
ShoppingCart "1" *-- "*" LineItem
LineItem "*" -- "1" Product
Order "1" -- "*" Payment

@enduml

